Extract Structured Data.code:
// Extract structured fields via the Responses API, constrained to a JSON schema.
deepResearch(
  `Extract the contact details from the message below.\n\nMESSAGE:\n${$.data.message}`,
  {
    model: 'gpt-4o',
    tools: [],
    text: {
      format: {
        type: 'json_schema',
        name: 'contact',
        schema: {
          type: 'object',
          properties: {
            name:  { type: 'string' },
            email: { type: 'string' },
            phone: { type: 'string' },
          },
          required: ['name'],
          additionalProperties: false,
        },
      },
    },
  }
);

